def calculate_scores(d, m):
    defect_rate = d['units_defective'] / d['units_received']
    measured_quality = max(0, 100 - defect_rate * 1000)  # 10% defects -> 0
    rating = d.get('buyer_quality_rating')
    quality = measured_quality if rating is None else 0.7 * measured_quality + 0.3 * (rating * 20)

    delivery = 100 * min(d['orders_on_time'], d['orders_total']) / d['orders_total']

    price, bench = d.get('avg_unit_price_cad'), d.get('benchmark_unit_price_cad')
    if price and bench:
        price_score = max(0, min(100, 100 - (price / bench - 1) * 200))  # 10% over benchmark -> 80
    else:
        price_score = 50

    s = {'DIM_QUALITY': round(quality, 1), 'DIM_DELIVERY': round(delivery, 1), 'DIM_PRICE': round(price_score, 1)}
    total = sum(s[k] * m[k]['weight'] for k in s)
    return {'compositeScore': round(total, 2), 'breakdown': s}
